-- Seed: the seven SANIA catalogue products. Prices, sizes and stock are intentionally NOT set: configure in Admin.



-- Front + back images (served from /public/products)
select p.id, '/products/'||lower(p.code)||'-'||v.kind||'.webp', v.kind, v.kind='front', v.ord
from products p cross join (values ('front',0),('back',1)) v(kind,ord)
where p.code like 'SAN-0%' and not exists (select 1 from product_images i where i.product_id=p.id);
